async refund(id: string, userId: string) {
  const order = await this.repo.find(id);
  if (!order) throw new NotFound(id);
  if (order.userId !== userId) throw new Forbidden();
  if (order.status !== "DELIVERED") throw new InvalidState(order.status);
  order.status = "REFUNDED";
  await this.repo.save(order);
  await publish({ type: "order.refunded", orderId: id });
}
